head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
scwin.strBzProcsNo;
scwin.attach_seq;
scwin.vScrenID = "ULDSTF21700.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

//청구연도 기본셋팅
scwin.fn_init = function() {
    var urlYear = "/listingCommon.do?method=listGeneral" + "&outputMessageId=LIST_KOSDAQ_NEW_PREEXAM_YEAR" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstsrch.select.kosdaq.prelminvstgclm.condition_year";
    dts_List_Year.DataID = encodeURI(urlYear);
    dts_List_Year.reset();
};
scwin.fn_list_sync = function() {
    var yearTmp;
    if ($c.stf.getObjectValue(cmb_Year) == "") {
        yearTmp = $c.ut.cGetToday("yyyymmdd").substring(0, 4);
    } else {
        yearTmp = $c.stf.getObjectValue(cmb_Year);
    }
    var url = "/listingCommon.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=listGeneral" + "&outputMessageId=LIST_KOSDAQ_NEW_PREEXAM_YEAR_FILE" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstsrch.select.kosdaq.prelminvstgclm.condition_year_file" + "&{P}param01=" + yearTmp;
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
};


//파일 다운로드
scwin.fn_filedown = function(strBzProcsNo, attach_seq) {
    location.href = "/filedownload.do?file_id=" + scwin.strBzProcsNo + "&attach_seq=" + scwin.attach_seq + "&gubun=13&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_08;
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07); // 엑셀
    $c.data.downloadGridViewExcel(grd_List, "연도별 파일검색", "", "8");
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    $c.cm.CloseWin(rowcount, grd_List);
};
scwin.grd_List_OnDblClick = function(row, colid) {
    if (dts_List.getRowStatus(dts_List.getRowPosition()) == 0) {
        if (colid == "ATTACH_FILE_NM_1") {
            //청구서파일
            if (dts_List.getCellData(row, "ATTACH_FILE_NM_1") != "") {
                $c.elw.fn_filedown(dts_List.getCellData(row, "BZ_PROCS_NO"), 10);
            }
        } else if (colid == "ATTACH_FILE_NM_2") {
            //주주명부등파일
            if (dts_List.getCellData(row, "ATTACH_FILE_NM_2") != "") {
                $c.elw.fn_filedown(dts_List.getCellData(row, "BZ_PROCS_NO"), 11);
            }
        } else if (colid == "ATTACH_FILE_NM_3") {
            //위원회안건파일
            if (dts_List.getCellData(row, "ATTACH_FILE_NM_3") != "") {
                $c.elw.fn_filedown(dts_List.getCellData(row, "BZ_PROCS_NO_2"), 2);
            }
        }
    }
};
scwin.btn_Search_onclick = function() {
    scwin.fn_list_sync();
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page_1);
    $c.cm.CloseWin(rowcount, grd_List);
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_Top); //패널라운드	
    scwin.fn_init();
    scwin.strBzProcsNo = $c.stf.getQuery(frame.srcUrl, "BZ_PROCS_NO");
    scwin.fn_list_sync();
};
